// ===== AUTO-BLOCK SAFEGUARD CHECK =====
// Never auto-block: internal/private IPs, explicitly allowlisted IPs,
// critical assets, or when auto-block is globally disabled.
function ipInCidr(ip, cidr) {
  try {
    const [range, bits] = cidr.split("/");
    const mask = ~(2 ** (32 - Number(bits)) - 1);
    const ipToInt = s => s.split(".").reduce((acc, o) => (acc << 8) + Number(o), 0) >>> 0;
    return (ipToInt(ip) & mask) === (ipToInt(range) & mask);
  } catch (e) { return false; }
}

const items = $input.all();
return items.map(item => {
  const a = item.json;
  const cfg = a._config || {};
  const ip = a.srcIp;
  const reasons = [];

  if (!cfg.autoBlockEnabled) reasons.push("Auto-block disabled globally in Configuration Center");
  if (!ip) reasons.push("No source IP present to block");
  if (ip && (cfg.internalCidrs || []).some(c => c && ipInCidr(ip, c))) reasons.push("IP is internal/private - never auto-block");
  if (ip && (cfg.allowlistIps || []).includes(ip)) reasons.push("IP is explicitly allowlisted");
  if ((cfg.criticalAssets || []).includes(a.agentName) || (cfg.criticalAssets || []).includes(a.agentId)) reasons.push("Agent is a critical asset - block requires human approval");
  if (a._ai?.confidence !== undefined && a._ai.confidence < 70) reasons.push("AI confidence below 70% - too low to auto-block");
  if (a.ruleLevel < (cfg.criticalThreshold || 12)) reasons.push("Rule level below critical auto-block threshold");

  const safeToBlock = reasons.length === 0 && a._ai?.auto_block_recommended === true;
  return { json: { ...a, _blockSafe: safeToBlock, _blockBlockedReasons: reasons } };
});

